solution:
function solve(n, edges, start) {
  const adj = Array.from({ length: n }, () => [])
  for (const [u, v] of edges) {
    adj[u].push(v)
    adj[v].push(u)
  }
  adj.forEach((a) => a.sort((p, q) => p - q))

  const dikunjungi = Array(n).fill(false)
  const antrean = [start]
  dikunjungi[start] = true
  const urutan = []
  while (antrean.length > 0) {
    const u = antrean.shift() // ambil dari depan antrean
    urutan.push(u)
    for (const v of adj[u]) {
      if (!dikunjungi[v]) {
        dikunjungi[v] = true
        antrean.push(v)
      }
    }
  }
  return urutan
}
